import type { MatchPhase, PlayerId, ShotCommand } from './game';
import type { Vec3 } from './math';

export type SimulationEvent =
  | { type: 'shot-accepted'; command: ShotCommand }
  | { type: 'shot-rejected'; command: ShotCommand; reason: string }
  | { type: 'ball-stopped'; playerId: PlayerId; position: Vec3 }
  | { type: 'ball-holed'; playerId: PlayerId; holeId: string; strokes: number }
  | { type: 'ball-reset'; playerId: PlayerId; position: Vec3; penaltyStrokes: number };

export type PresentationEvent =
  | { type: 'phase-changed'; phase: MatchPhase }
  | { type: 'active-player-changed'; playerId: PlayerId }
  | { type: 'power-preview'; normalizedPower: number }
  | { type: 'scoreboard-requested'; visible: boolean }
  | { type: 'camera-reset-requested'; playerId: PlayerId };

export interface EventSink<TEvent> {
  emit(event: TEvent): void;
}

export interface EventSource<TEvent> {
  subscribe(listener: (event: TEvent) => void): () => void;
}
