--- src/contracts/services.ts
import type { Course, Hole } from '../courses/types';
import type { GameState } from '../app/GameState';
import type { MatchDTO, MatchSettings, PlayerProfile, ShotCommand } from './game';
import type { SimulationEvent } from './events';
import type { Vec3 } from './math';

export interface PhysicsBallSnapshot {
  position: Vec3;
  linearVelocity: Vec3;
  angularVelocity: Vec3;
  sleeping: boolean;
}

export interface SimulationService {
  loadHole(hole: Hole, players: readonly PlayerProfile[]): Promise<void> | void;
  submitShot(command: ShotCommand): boolean;
  step(deltaSeconds: number): readonly SimulationEvent[];
  getBall(playerId: string): PhysicsBallSnapshot | undefined;
  dispose(): void;
}

export interface CourseRepository {
  listCourses(): Promise<readonly Course[]>;
  getCourse(courseId: string): Promise<Course>;
}

export interface MatchService {
  createMatch(settings: MatchSettings, players: readonly PlayerProfile[]): MatchDTO;
  applySimulationEvent(match: MatchDTO, event: SimulationEvent): MatchDTO;
}

export interface SaveService {
  load(): Promise<unknown>;
  save(state: unknown): Promise<void>;
}

export interface GameRuntime {
  readonly state: Readonly<GameState>;
  start(): Promise<void>;
  pause(): void;
  resume(): void;
  dispose(): void;
}
